  "inlineSchema": "// Prisma schema — «Семейный бюджет»\n// User владеет семьёй (членами), справочниками и счетами.\n// Доходы/расходы привязаны к члену семьи и типам/категориям.\n\n// Клиент генерируется в обычную папку исходников (не в скрытый node_modules/.prisma).\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma-client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n/// Пользователь системы (владелец данных бюджета)\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  password  String /// хэш пароля (bcrypt)\n  name      String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  familyMembers     FamilyMember[]\n  incomeTypes       IncomeType[]\n  expenseCategories ExpenseCategory[]\n  accounts          Account[]\n}\n\n/// Член семьи, от имени которого учитываются доходы и расходы\nmodel FamilyMember {\n  id        String   @id @default(uuid())\n  userId    String\n  name      String\n  /// Например: self, spouse, child\n  relation  String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user     User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  incomes  Income[]\n  expenses Expense[]\n\n  @@index([userId])\n}\n\n/// Тип дохода (зарплата, подработка и т.д.) — в разрезе пользователя\nmodel IncomeType {\n  id        String   @id @default(uuid())\n  userId    String\n  name      String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user    User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  incomes Income[]\n\n  @@unique([userId, name])\n  @@index([userId])\n}\n\n/// Категория расхода — в разрезе пользователя\nmodel ExpenseCategory {\n  id        String   @id @default(uuid())\n  userId    String\n  name      String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user     User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  expenses Expense[]\n\n  @@unique([userId, name])\n  @@index([userId])\n}\n\n/// Счёт / кошелёк (может быть несколько у одного пользователя)\nmodel Account {\n  id        String   @id @default(uuid())\n  userId    String\n  name      String\n  balance   Decimal  @default(0) @db.Decimal(15, 2)\n  currency  String   @default(\"RUB\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user     User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  incomes  Income[]\n  expenses Expense[]\n\n  @@index([userId])\n}\n\n/// Запись о доходе\nmodel Income {\n  id          String   @id @default(uuid())\n  amount      Decimal  @db.Decimal(15, 2)\n  /// Дата фактического поступления\n  occurredAt  DateTime @default(now())\n  description String?\n\n  familyMemberId String\n  incomeTypeId   String\n  /// Если null — без привязки к счёту\n  accountId      String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  familyMember FamilyMember @relation(fields: [familyMemberId], references: [id], onDelete: Cascade)\n  incomeType   IncomeType   @relation(fields: [incomeTypeId], references: [id], onDelete: Restrict)\n  account      Account?     @relation(fields: [accountId], references: [id], onDelete: SetNull)\n\n  @@index([familyMemberId])\n  @@index([incomeTypeId])\n  @@index([accountId])\n}\n\n/// Запись о расходе\nmodel Expense {\n  id          String   @id @default(uuid())\n  amount      Decimal  @db.Decimal(15, 2)\n  occurredAt  DateTime @default(now())\n  description String?\n\n  familyMemberId    String\n  expenseCategoryId String\n  accountId         String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  familyMember    FamilyMember    @relation(fields: [familyMemberId], references: [id], onDelete: Cascade)\n  expenseCategory ExpenseCategory @relation(fields: [expenseCategoryId], references: [id], onDelete: Restrict)\n  account         Account?        @relation(fields: [accountId], references: [id], onDelete: SetNull)\n\n  @@index([familyMemberId])\n  @@index([expenseCategoryId])\n  @@index([accountId])\n}\n",
